preConditionHook:
// THE BOOK'S LITERAL DOUBLE-TOP ENTRY: after a double top, sell when price
// breaks entryTicks below THE LOWEST POINT OF THE DIP between the two tops.
// The long
// mirror buys above the high of the bounce between the two bottoms of a double
// bottom.
//
// Kept apart from DoubleExtremeBreakout because THE LEVEL IS DIFFERENT: that
// rule triggers at the pattern's own level, this one at the extreme BETWEEN
// the two pivots, which sits much further away. Worth authoring precisely
// because Brooks says it usually fails -- "that is rarely successful because
// 80 percent of breakouts fail" -- which under the per-placement negate toggle
// is a testable claim in both directions.
//
// THE PATTERN is spelled exactly as in DoubleExtremePullback and
// DoubleExtremeBreakout: the two most recent CONFIRMED swing lows within
// matchTicks of each other, the more recent confirmed no more than
// patternWindow bars ago. matchTicks and pivotLookback ARE PROMOTED, the
// merged parameters naming neither. Ticks division-first,
// ctx.MinMove() / ctx.PriceScale() computed once into tickSz; both are
// per-symbol constants (VERIFIED). entryTicks keeps Brooks's one tick.
//
// THE BETWEEN-PIVOTS EXTREME is one more piece of retained state than any
// other rule in this bucket: the highest high over the bars from the newer
// pivot back to the older one, inclusive, scanned with the pivots' own
// bars-ago counts as the loop bounds -- the shape ChannelBounceFractionTarget
// uses when a span is defined by a pivot rather than by an input. The scan is
// INSIDE the pattern guard because an unguarded loop would run from a -1 bar
// index, which is a future bar. The guard costs nothing in Max Bars Back: the
// pivot scan above already reaches pivotLookback - 1 + strength every bar.
//
// PIVOT SCAN inlined from SwingHigh.json per the B-list decision, occurrences
// 1 and 2 only (occurrence 3+ is unmeasured). MEASURED (EL_Swing_Probe.txt,
// @ES 60 min): the pivot bar is AT OR ABOVE the `strength` OLDER bars and
// STRICTLY ABOVE the `strength` NEWER bars -- bars-ago indexing, so the newer
// bars are the smaller k and take el_gt / el_lt, the older el_ge / el_le;
// confirmation lag exactly `strength`; candidate offsets
// strength..pivotLookback-1, the neighbourhood reaching `strength` bars past
// the window. The comparisons carry the 2.22e-12 relational tolerance. A flat
// run of equal lows is ONE pivot, not N. The -1 sentinel is guarded on both
// bar indices.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
tickSz = ctx.MinMove() / ctx.PriceScale();
pivS = (int)strength;
pivW = (int)pivotLookback;
nHi = 0;
nLo = 0;
hiPx1 = -1.0;
hiBar1 = -1.0;
hiPx2 = -1.0;
hiBar2 = -1.0;
loPx1 = -1.0;
loBar1 = -1.0;
loPx2 = -1.0;
loBar2 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHi < 2) {
        nHi = nHi + 1;
        if (nHi == 1) { hiPx1 = high[j]; hiBar1 = (double)j; }
        if (nHi == 2) { hiPx2 = high[j]; hiBar2 = (double)j; }
    }
    if (okLo && nLo < 2) {
        nLo = nLo + 1;
        if (nLo == 1) { loPx1 = low[j]; loBar1 = (double)j; }
        if (nLo == 2) { loPx2 = low[j]; loBar2 = (double)j; }
    }
}
haveDb = (loBar1 != -1.0) && (loBar2 != -1.0) && el_le(loBar1, patternWindow)
    && el_le(std::fabs(loPx1 - loPx2), matchTicks * tickSz);
haveDt = (hiBar1 != -1.0) && (hiBar2 != -1.0) && el_le(hiBar1, patternWindow)
    && el_le(std::fabs(hiPx1 - hiPx2), matchTicks * tickSz);
bounceHi = 0.0;
if (haveDb) {
    bounceHi = high[(int)loBar1];
    for (int k = (int)loBar1 + 1; k <= (int)loBar2; ++k) {
        if (el_gt(high[k], bounceHi)) bounceHi = high[k];
    }
}
dipLo = 0.0;
if (haveDt) {
    dipLo = low[(int)hiBar1];
    for (int k = (int)hiBar1 + 1; k <= (int)hiBar2; ++k) {
        if (el_lt(low[k], dipLo)) dipLo = low[k];
    }
}
